def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the non-frame 3 that marks the center of the pattern.
    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == 3 and 3 <= r <= 9 and 4 <= c <= 10]
    if not markers:
        return out
    mr, mc = markers[0]

    for r in range(3, 10):
        for c in range(4, 11):
            if (r, c) == (mr, mc):
                out[r][c] = 3
            else:
                d = max(abs(r - mr), abs(c - mc))
                out[r][c] = 2 if d % 2 == 0 else 4
    return out
